"""Remove only unchanged instruction files previously generated by Research Ops."""

from __future__ import annotations

import hashlib
from collections.abc import Iterable
from pathlib import Path

_BRANCH_PREFIX = (
    "# Research Ops Branch\n\n"
    "- Work only on the objective supplied in the Session Brief.\n"
)
_BRANCH_SUFFIX = "- Do not write secrets into this workspace.\n"
GENERATED_AGENTS = frozenset({
    _BRANCH_PREFIX
    + "- Research Ops Handoff is user-controlled. Do not run `rops handoff`, call a "
    "handoff API, or create/update `RESEARCH_OPS_HANDOFF.md` unless the user "
    "explicitly asks to end the round, hand off, or submit a result.\n"
    + _BRANCH_SUFFIX,
    _BRANCH_PREFIX
    + "- Record durable outcomes through Research Ops Handoff.\n"
    + _BRANCH_SUFFIX,
    "# Program Desk\n\n"
    "- Coordinate this Program; do not implement task work in this directory.\n"
    "- Create or continue Research Ops WorkItems for implementation.\n"
    "- Keep only direction-level notes, decisions, and playbooks here.\n"
    "- Never write secrets into this workspace.\n",
})


def cleanup_generated_instructions(
    workspaces: Iterable[Path], *, backup_dir: Path | None = None
) -> list[dict[str, str]]:
    """Dry-run by default. Never follow file symlinks or alter customized instructions."""
    report = []
    paths = sorted({workspace.resolve() / "AGENTS.md" for workspace in workspaces})
    for path in paths:
        if path.is_symlink() or not path.is_file():
            continue
        if path.stat().st_size > 64 * 1024:
            report.append({"path": str(path), "status": "customized"})
            continue
        data = path.read_bytes()
        text = data.decode("utf-8", errors="replace")
        entry = {"path": str(path), "sha256": hashlib.sha256(data).hexdigest()}
        if text not in GENERATED_AGENTS:
            report.append({**entry, "status": "customized"})
            continue
        if backup_dir is None:
            report.append({**entry, "status": "generated"})
            continue
        backup = backup_dir / hashlib.sha256(str(path).encode()).hexdigest() / "AGENTS.md"
        backup.parent.mkdir(parents=True, exist_ok=True)
        if backup.exists() and backup.read_bytes() != data:
            raise ValueError(f"Backup already contains a different file: {backup}")
        backup.write_bytes(data)
        # Do not remove a file edited while the audit/backup was in progress.
        if path.is_symlink() or path.read_bytes() != data:
            report.append({**entry, "status": "changed_during_cleanup"})
            continue
        path.unlink()
        report.append({**entry, "status": "removed", "backup": str(backup)})
    return report
